配置示例.RDMA 共享设备插件 ConfigMap:
kind: ConfigMap
metadata:
  name: rdma-devices
  namespace: kube-system
data:
  config.json: |
    {
      "periodicUpdateInterval": 300,
      "configList": [{
        "resourceName": "rdma_shared_device_a",
        "rdmaHcaMax": 1000,
        "selectors": {
          "vendors": ["15b3"],
          "deviceIDs": ["101b", "101d"],
          "drivers": ["mlx5_core"],
          "linkTypes": ["IB", "Ethernet"]
        }
      }]
    }
